import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAZ: [CaseTemplate] = [libraryKeyboard, mailboxFirework, dumpsterDigger, shelterGlass, sealcoatScam, boosterRaffle, closedHotTub, boatLakeDWI, scooterShove, yogaCubby, airportPass, fakeSickNote, bakeSaleBox, motelTv, karaokeMic, hydrantFlood, skateRamp, schoolLoiter, checkoutShove, roadCones, ebayBrick, fittingLayers, gateArm, wifiBorrow, curbCouch, barrelBurn, paradeRoute, weddingCrasher, scooterHome, casinoChips, offeringPlate, fakeDealerTag, pharmacyPills, shoesOut, fakeSticker, bikeShareRiver, neighborTree, forwardedMail, foundWalletCash, dogParkBrawl, tattooDeposits, coopChickens, weddingDjNoShow, shovelSpot, refundCheat, mallGrabRun, busSpit, trailBike, lostDogReward, siphonedDiesel]

    static let libraryKeyboard = SmallCases.make(
        key: "story.libraryKeyboard",
        category: .property,
        headlines: ["Patron Smashes Library Computer After Session Timer Ends"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a public library, causing damage of $460, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} smashed a public computer's keyboard and screen on {DATE} when the session timed out. The timer ended at 2 p.m. and the slam came a minute later. The keyboard and screen cost $460 to replace.",
        state: [E(.video, 3, "Library Camera", "{D} slams the keyboard into the screen."), E(.document, 2, "Repair Invoice", "$460 for a new keyboard and screen.")],
        defense: [E(.statement, 1, "Glitch", "{DL} says the machine froze and ate {D.his} work.")],
        role: "Librarian",
        exam: [.direct("What happened at the public computer at 2 p.m.?", "\"The session timer ran out at 2 p.m. About a minute later, {D} slammed the keyboard into the screen, damaging both.\""), .direct("What does the library camera show?", "\"{DL} at the station, the timer ending, and then {DL} bringing the keyboard down against the monitor. Other patrons look up.\""), .direct("What did the damage cost?", "\"$460 to replace the keyboard and the screen. The repair invoice is in our file.\""), .direct("How is the public computer area set up?", "\"We have eight stations in the main reading room, and each one logs a patron out after a set session. A warning pops up on the screen a few minutes before time runs out.\""), .direct("Where were you when you heard the noise?", "\"I was at the circulation desk about thirty feet away. I heard a loud crack, looked up, and saw {DL} standing over station five with the keyboard still in hand.\""), .direct("What condition was the equipment in afterward?", "\"The screen was cracked across the middle and the keyboard had split with keys scattered on the desk. Both were unusable, and we had to pull the station out of service that afternoon.\""), .cross("Did the computer freeze before the session ended?", "\"The log shows a freeze at some point. I cannot say exactly when, or whether {D.he} lost work.\""), .cross("Was {D} warned about time limits before?", "\"Yes, {D.he} had been reminded of the limits on earlier visits. That is part of how we run the stations.\""), .cross("Did the defendant threaten anyone?", "\"No. {DL} was frustrated and loud, but did not threaten a person.\""), .cross("You did not see the keyboard hit the screen yourself, did you?", "\"I saw {DL} standing there with it right after the crack. The camera footage is what shows the swing itself, and I reviewed it with my director that afternoon.\""), .cross("Patrons sometimes complain the stations lock up, don't they?", "\"We have had reports of slow stations and freezes over the years. I cannot say whether station five froze that day, only that the log shows some kind of freeze.\"")],
        theory: ("{D} smashed a computer.", "A glitch."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had been warned about time limits.", "The log shows a freeze."),
        defendant: [.direct("Did you smash the keyboard and screen?", "\"I slammed the keyboard down. I was angry, and I did not mean to break the screen, but it did.\""), .direct("Why were you so upset?", "\"I lost my work when the session timed out. I had been working on an application for hours.\""), .direct("Had you saved your work?", "\"No. I did not save, and that was my mistake. I did not know the timer would end so suddenly.\""), .direct("What were you working on at the station?", "\"I was filling out an online job application with a long essay section. I had been typing for most of the session and the form had not autosaved anywhere.\""), .direct("What exactly did the screen do?", "\"It stopped responding, then the whole session closed and sent me back to the login page. Everything I had typed was gone before I could even click anything.\""), .direct("What did you do right after the damage?", "\"I stood there shaking for a moment, then told the librarian I would stay until someone talked to me. I did not leave and I did not argue.\""), .cross("You had been warned about the time limits, hadn't you?", "\"Yes. I knew the rules. I should have watched the clock.\""), .cross("$460 of damage in a minute. Do you accept responsibility?", "\"I do. I am willing to pay for it, and I am sorry.\""), .cross("Other people were in the room. Weren't you afraid of hurting someone?", "\"I was not thinking. I should have walked away.\""), .cross("The timer reached zero at 2 p.m., correct?", "\"Yes, it did. I think the machine froze for a bit before that, but I cannot swear to the exact minute and I was not watching the clock like I wish I had.\""), .cross("You chose to swing the keyboard, didn't you?", "\"I did. Nothing made me do it except my own temper, and I am not blaming the computer for what my hands did.\"")],
        openings: ("At 2 p.m. the session timer on a public library computer ran out, and about a minute later {D} brought a keyboard down onto the screen. The library camera recorded the swing, and replacing the keyboard and screen cost $460.", "{D} was filling out a long application when the machine locked up and erased hours of typing. The evidence will show a freeze in the log, a person with no history of violence, and someone who stayed to take responsibility."),
        closings: ("The library camera shows the slam, the invoice shows $460, and {D} admits swinging the keyboard. Frustration with a timer does not give anyone the right to wreck property that belongs to the public.", "The log shows the machine froze, and the work {D} lost was real. {D} threatened no one, stayed at the scene, and offered to pay, so the damage should be measured by that honest accounting rather than by a single angry minute."),
        timeline: [(0, "2 p.m.: the timer ends."), (0, "2:01 p.m.: the slam.")],
        identified: "Library Camera",
        mood: .indifferent)

    static let mailboxFirework = SmallCases.make(
        key: "story.mailboxFirework",
        category: .property,
        headlines: ["Firework Blows Up Neighbor's Mailbox at Dusk"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, causing damage of $180, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} put a firework in a neighbor's mailbox on {DATE} and blew it apart. The tube was placed at dusk and the blast followed a minute later. The mailbox was blown apart and cost $180 to replace.",
        state: [E(.video, 3, "Porch Camera", "{D} places a tube in the mailbox and runs."), E(.document, 2, "Replacement Receipt", "$180 for a new mailbox.")],
        defense: [E(.statement, 1, "Prank", "{DL} says it was a prank.")],
        role: "Neighbor",
        exam: [.direct("What happened at your mailbox?", "\"At dusk, {D} put a firework tube in my mailbox and ran. A minute later it blew the mailbox apart.\""), .direct("What does your porch camera show?", "\"It shows {DL} approaching, placing the tube in the box, and running off. The blast comes about a minute later.\""), .direct("What did the replacement cost?", "\"$180 for a new mailbox. I have the receipt.\""), .direct("What was the mailbox like before that evening?", "\"It was a standard metal box on a post at the curb, painted black, about three years old. It held up fine through storms and never had so much as a dent.\""), .direct("Where were you when it happened?", "\"I was inside near the front window making dinner. I heard a sharp bang that rattled the glass, ran to the door, and found pieces of the box scattered across the yard.\""), .direct("What did you find outside?", "\"The door was blown off and the sides were torn open and curled outward. Scorch marks covered the post, and bits of paper from the day's mail were burnt and spread over the grass.\""), .cross("Was anyone near the mailbox when it went off?", "\"No. Nobody was nearby, and no one was hurt.\""), .cross("Is {D} someone you know?", "\"Yes, {DL} is a neighbor. We had no serious feud that I know of.\""), .cross("Was the firework lit before it went into the mailbox?", "\"I believe {D.he} lit it. The camera shows a flash right before {D.he} ran.\""), .cross("You never actually saw the defendant light anything, did you?", "\"No. I only know it from the porch camera, which shows {DL} bent over the box and then running. The flame itself is hard to make out on the footage.\""), .cross("How many seconds passed between the defendant leaving and the blast?", "\"It was close to a minute on the camera clock. {D.He} was already well down the street, and nobody was standing anywhere near the mailbox when it went off.\"")],
        theory: ("{D} blew up a mailbox.", "A prank."),
        allocution: "\"I'm sorry.\"",
        truths: ("The tube was lit by {DL}.", "No one was nearby."),
        defendant: [.direct("Did you put the firework in the mailbox?", "\"Yes, I did. It was a prank, and I did not think about the damage it would do.\""), .direct("Where did you get the firework?", "\"From a roadside stand. I bought it with a few others for fun.\""), .direct("Did you mean to hurt anyone?", "\"No. I made sure no one was around, and I never meant to hurt anybody.\""), .direct("Why did you pick that mailbox?", "\"It was a dumb choice. The tube was left over from a stand I visited that week, and the mailbox was close to where I was walking at dusk.\""), .direct("Describe what you did with the tube.", "\"I lit the fuse, set the tube inside the box, and closed the little door. Then I ran, because I knew it would go off in seconds.\""), .direct("What went through your mind afterward?", "\"When I heard the blast and saw the damage the next day, my stomach dropped. I realized it was much bigger than anything I had pictured in my head.\""), .cross("You lit it and ran, didn't you?", "\"Yes. I see how that looks. I was a fool.\""), .cross("A mailbox is blown apart. Aren't you responsible?", "\"I am. I will pay for a new one.\""), .cross("You could have hurt someone, couldn't you?", "\"I thought no one was near. I now see that was not a good assumption.\""), .cross("You looked around first to see if anyone was nearby, right?", "\"I glanced both ways down the street and saw no one. I understand now that a quick glance is not the same as making sure.\""), .cross("Fireworks can start fires or injure a person, can't they?", "\"Yes, they can. A fire in a box full of paper could have spread to the house, and I did not think that through at all.\"")],
        openings: ("At dusk {D} lit a firework tube, dropped it in a neighbor's mailbox, and ran. A minute later the box exploded, and the porch camera caught {D} bending over it and leaving.", "The defense will present a foolish prank by someone who looked around first and believed the street was empty. Nobody was hurt, nothing else burned, and {D} accepts the cost of a new box."),
        closings: ("A lit firework in a neighbor's mailbox is not a harmless joke, and the porch camera shows who put it there. The $180 receipt and the blown apart box prove the damage.", "This was a thoughtless prank at dusk on an empty street, and the harm stopped at one mailbox. {D} admits it, will pay the $180, and has learned a hard lesson."),
        timeline: [(0, "Dusk: the tube is placed."), (0, "Dusk+1: the blast.")],
        identified: "Porch Camera",
        mood: .indifferent)

    static let dumpsterDigger = SmallCases.make(
        key: "story.dumpsterDigger",
        category: .publicOrder,
        headlines: ["Man Returns to Store Dumpster After Being Told Not To"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a grocery store, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} dug through a store dumpster on {DATE} after a written trespass notice. The notice was dated two weeks earlier. {D} was at the dumpster at 6 a.m., and deputies arrived ten minutes later.",
        state: [E(.document, 3, "Trespass Notice", "Signed notice dated two weeks earlier."), E(.statement, 2, "Store Manager", "Recognized {D} from the notice.")],
        defense: [E(.statement, 1, "Discarded", "{DL} says the food was thrown out.")],
        role: "Store manager",
        exam: [.direct("What did you see behind your store at 6 a.m. on {DATE}?", "\"{D} was digging through our dumpster. I recognized {D.him} from the written trespass notice we had issued two weeks earlier.\""), .direct("What was the notice?", "\"A written notice banning {DL} from our property, dated two weeks earlier. It's in evidence and it carries a signature line.\""), .direct("What happened next?", "\"I called deputies. They arrived about ten minutes later and spoke with {DL}. {DL} was still at the dumpster when they got there.\""), .direct("How do you know the person at the dumpster was {D}?", "\"I had spoken with {DL} in person two weeks earlier when I handed over the notice. I recognized {DL} right away from the back door, even before I saw a face.\""), .direct("What does the trespass notice say?", "\"It says {D.he} may not come onto our lot or any part of our property, and it carries {D.his} signature and the date. I keep a copy in the office.\""), .direct("What was behind the fence at the back of the store?", "\"Our dumpster sits inside a fenced enclosure near the loading dock. The gate was open that morning, and {D.he} was leaning over the edge sorting through bags.\""), .cross("{DL} says the food was thrown out, doesn't {D.he}?", "\"It was discarded, yes. But the dumpster is on our property, and we told {DL} not to come.\""), .cross("Did {DL} take anything of value?", "\"Food that we'd thrown out. I wouldn't say it had any value to us. It was the entering the property that bothered us.\""), .cross("Did {DL} cause any damage?", "\"No. I didn't see any damage. {D.He} wasn't hostile. {D.He} was digging and then stopped when deputies arrived.\""), .cross("The store was closed at 6 a.m., wasn't it?", "\"We open at 7:30, so yes, it was closed. I was there early to receive a produce delivery, which is why I was at the back door.\""), .cross("{D} left without any trouble when deputies came, didn't {D.he}?", "\"Yes. {D.He} climbed out, put the bag down, and spoke calmly to the deputies. I never saw any resistance or heard a raised voice.\"")],
        theory: ("{D} ignored a notice.", "Thrown-out food."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} signed the notice.", "The dumpster was behind a fence."),
        defendant: [.direct("Why were you at the dumpster?", "\"I was looking for food. Stores throw away good food, and I needed it. I wasn't there to cause trouble.\""), .direct("Did you know about the trespass notice?", "\"I got one. But I didn't think it applied to taking out what had been thrown away. I should have asked someone.\""), .direct("What did you do when deputies arrived?", "\"I stopped and talked to them. I didn't run or argue. I told them I only wanted food.\""), .direct("How often do you look through dumpsters for food?", "\"Only when I am out of money, maybe a few times a month. I check for sealed items and packaged food that is still within the date.\""), .direct("What did you understand the notice to cover?", "\"I thought it was about going inside the store, because that is where the trouble started. I honestly did not think it reached a trash bin out back.\""), .direct("What had you found that morning?", "\"A couple of bags of bread, some bagged salad, and a few yogurt cups. I had not taken them out of the enclosure yet when the deputies pulled in.\""), .cross("You'd been told in writing not to return, hadn't you?", "\"Yes. Two weeks earlier. I should have stayed away. I just didn't know where else to go.\""), .cross("It was 6 a.m., wasn't it?", "\"Yes. Early, before the store opened. I was hoping not to be noticed, and I know that makes it worse.\""), .cross("The dumpster is on the store's property, isn't it?", "\"Yes. I know that now. I thought garbage was free for anyone to take.\""), .cross("You signed that notice, didn't you?", "\"Yes, I signed it. I read it quickly at the time and did not argue, and I will not pretend otherwise now.\""), .cross("The fence and gate show it is a closed-off area, right?", "\"It is fenced, but the gate was standing open. I still knew it belonged to the store, and I should have asked first.\"")],
        openings: ("Two weeks after signing a written trespass notice, {D} was inside the fenced dumpster enclosure behind the store at 6 a.m. The store manager recognized {D} from that notice and called deputies, who arrived about ten minutes later.", "The defense will present a hungry person who went through food that was already thrown away, damaged nothing, and stopped the moment deputies arrived. {D} believed the notice was about the store itself, not the trash behind it."),
        closings: ("The notice was in writing, {D} signed it, and two weeks later {D} was back on the property. Whether the food was trash does not change the fact that the notice said stay off the lot.", "{D} wanted discarded bread and salad, broke nothing, and cooperated fully with deputies. A person who signed a notice and misread its reach has made an honest mistake and should not be treated as a danger."),
        timeline: [(0, "6 a.m.: {DL} is at the dumpster."), (0, "6:10 a.m.: deputies arrive.")],
        identified: "Trespass Notice",
        mood: .indifferent,
        genders: ["D": .male])

    static let shelterGlass = SmallCases.make(
        key: "story.shelterGlass",
        category: .property,
        headlines: ["Bus Shelter Glass Smashed With Rock After Missed Bus"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a transit authority, causing damage of $800, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} threw a rock through a bus shelter pane on {DATE} after a bus passed without stopping. The bus passed at 7 a.m. and the rock came two minutes later. The pane cost $800 to replace.",
        state: [E(.video, 3, "Shelter Camera", "{D} throws a rock."), E(.document, 2, "Replacement Invoice", "$800 for a new shelter pane.")],
        defense: [E(.statement, 1, "Anger", "{DL} says the bus did not stop.")],
        role: "Transit supervisor",
        exam: [.direct("What happened at the bus shelter?", "\"At 7 a.m. a bus passed, and two minutes later {D} threw a rock through the shelter's glass pane.\""), .direct("What does the shelter camera show?", "\"It shows {DL} picking up a rock and throwing it at the pane. The glass shattered.\""), .direct("What did it cost to replace?", "\"$800 for a new shelter pane. The invoice is in our records.\""), .direct("Where is this shelter and who uses it?", "\"It sits on a downtown corner along a busy commuter route, and dozens of riders wait there each morning. It has three glass panes and a metal bench.\""), .direct("What did you see on the camera after the rock hit?", "\"The pane shattered into small pieces across the sidewalk. {D.He} stood still for a few seconds, then walked off toward the next block.\""), .direct("How did you handle the damage on your end?", "\"We closed off the shelter with tape that morning and ordered a replacement pane. It took four days for the glass to arrive and be installed.\""), .cross("Did the bus stop nearby?", "\"The bus stopped a short distance away. {D.He} may not have realized it had stopped.\""), .cross("How many rocks did {D} throw?", "\"The camera shows two throws. I believe one broke the glass.\""), .cross("Was anyone hurt?", "\"No. No one was near the shelter at that moment.\""), .cross("Did the bus driver see the defendant waiting?", "\"I do not know. The driver told us the stop was crowded and may not have noticed one more rider near the curb, though the camera does show {DL} waving.\""), .cross("Is there a rule about when a bus must stop?", "\"Drivers are supposed to stop when a rider signals. They can also pull ahead to a safer spot, which is where this bus stopped, so it is not always a clear miss.\"")],
        theory: ("{D} broke a shelter.", "Anger."),
        allocution: "\"I'm sorry.\"",
        truths: ("The bus had stopped nearby.", "{DL} threw twice."),
        defendant: [.direct("Did you throw the rock?", "\"Yes, I did. I was angry that the bus did not stop for me.\""), .direct("Why were you so upset?", "\"I missed the bus, and I was going to be late for work. I took it out on the shelter.\""), .direct("How many rocks did you throw?", "\"One. It broke the glass. I did not throw a second.\""), .direct("What was riding on catching that bus?", "\"I had a job interview at eight and had already been late once to a shift that month. Missing that bus meant missing the next one too.\""), .direct("What did you see as the bus went by?", "\"I watched it roll past me with the lights on and no brake. I waved my arm, and it kept going until the corner.\""), .direct("What did you do after the glass broke?", "\"I stood there, startled at the noise. Then I walked away and called the office to say I would be late, and I felt sick about it all day.\""), .cross("The camera shows two throws, doesn't it?", "\"I remember one. It may have looked like two. It was quick.\""), .cross("The bus had stopped nearby, hadn't it?", "\"I did not see it. I thought it had passed me.\""), .cross("An $800 pane. Will you pay?", "\"I will pay it. I am deeply sorry.\""), .cross("You picked up the rock before you ever knew whether the bus would stop, didn't you?", "\"I picked it up when the bus went by. I did not look to see if it pulled over farther down, and I should have.\""), .cross("The shelter was not what you were angry at, was it?", "\"No. I was angry at the bus and at myself. The shelter was just in front of me, and it paid for my temper.\"")],
        openings: ("At 7 a.m. a bus passed {D} at a stop without slowing, and two minutes later {D} threw a rock through a pane of the shelter. A camera recorded the throw, and the pane cost $800 to replace.", "The defense will present a rider with a job interview who watched the bus drive past and lost {D.his} temper for a moment. {D} is ashamed of the damage and ready to pay for it."),
        closings: ("The shelter camera shows a rock thrown at glass, and the invoice shows $800 for the pane. Anger at a missed bus does not excuse breaking something that serves every other rider.", "One rock, one broken pane, and a person who admits it and will make it right. A missed ride is not a crime, but breaking glass over it is a poor reaction that can still be repaired."),
        timeline: [(0, "7 a.m.: the bus passes."), (0, "7:02 a.m.: the rock.")],
        identified: "Shelter Camera",
        mood: .indifferent)

    static let sealcoatScam = SmallCases.make(
        key: "story.sealcoatScam",
        category: .whiteCollar,
        headlines: ["Driveway Crew Takes Deposit, Sprays Watered-Down Coating"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $700, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took $700 for driveway sealing on {DATE} and sprayed a watery coat that washed off. The crew sprayed the coat in the morning and it washed off the next day. {V} paid $700 for the job.",
        state: [E(.physical, 3, "Driveway", "Coating washes away with a hose."), E(.document, 2, "Invoice", "An invoice for driveway sealing.")],
        defense: [E(.statement, 1, "Weather", "{DL} says rain ruined the coat.")],
        role: "Homeowner",
        exam: [.direct("What did you pay {D} for?", "\"$700 for sealing my driveway. {D}'s crew sprayed a coating on in the morning.\""), .direct("What happened to the coating?", "\"It washed off the next day. When I sprayed it with a hose, it ran off like water.\""), .direct("What did the drums look like?", "\"I did not see inside them. The coating looked thin and watery as it went on.\""), .direct("When did the crew arrive and what did they do?", "\"They showed up around eight in the morning with a trailer, two drums, and a spray wand. They cleaned the surface with a blower, sprayed it black, and were gone before noon.\""), .direct("How did the driveway look right after the job?", "\"It was dark and glossy for a few hours, and I was pleased with it. By the next afternoon it had gone gray and streaky in the tire tracks.\""), .direct("What did you do when you saw the problem?", "\"I rubbed my shoe across it and black came off, so I took the hose to a corner. Within a minute the coat ran off in a thin gray stream onto the lawn.\""), .cross("Did it rain after the job?", "\"It did not rain that day. I was told later that rain might have affected it.\""), .cross("Did the defendant offer a refund?", "\"Eventually, yes. {D.He} offered a refund, but not before I complained.\""), .cross("Did you see the crew's equipment?", "\"I saw drums and a sprayer. I am not an expert on sealer.\""), .cross("You paid by check before the work started, didn't you?", "\"I paid half up front and the rest when the crew finished, which came to $700 in all. I would not have handed over the second half if I had known.\""), .cross("You cannot say what was inside those drums, can you?", "\"That is right, I never looked inside them. I can only tell you what came out of the wand and how quickly the hose took it away.\"")],
        theory: ("{D} sold bad sealing.", "Bad weather."),
        allocution: "\"I'm sorry.\"",
        truths: ("No rain fell that day.", "The drums held mostly water."),
        defendant: [.direct("Why did the sealer wash off?", "\"I think it was rain. Sealer needs time to cure, and rain can wash it off.\""), .direct("What was in your drums?", "\"Sealer. I bought it from a supplier, and I diluted it a little, which is common.\""), .direct("Did you offer a refund?", "\"Yes. I offered a refund when {V} complained. I did not want a dispute.\""), .direct("Walk us through how you prepared the sealer.", "\"I mixed it from the drums with some added water so it would spread evenly. I have always thinned it a little, and I did the same on this driveway.\""), .direct("What was the weather like that week?", "\"I remember clouds building in the afternoon and a few drops that evening. I assumed it rained harder overnight and softened the coat before it cured.\""), .direct("How did you handle the homeowner's complaint?", "\"I came out after the call and looked at the driveway myself. I offered the refund on the spot because I did not want an argument.\""), .cross("No rain fell that day, did it?", "\"I thought there was rain. Maybe I got the dates wrong.\""), .cross("The drums were mostly water, weren't they?", "\"I diluted the product. I did not think I had made it too thin.\""), .cross("You took $700 for a job that washed off with a hose, didn't you?", "\"Yes, and I should have done better. That is why I offered the refund.\""), .cross("Sealer is supposed to cure for twenty-four hours, correct?", "\"It is, and that is why I blame the damp. I will admit I should have checked the forecast before I started.\""), .cross("You thinned it so much that a garden hose removed it, didn't you?", "\"I thinned it more than I should have, I will not deny that. I wanted the job to go further on the same drums.\"")],
        openings: ("{V} paid {D} $700 to seal a driveway, and the crew sprayed a dark coat that washed off with a garden hose the next day. The State will show that the drums held mostly water and that no rain fell that day.", "The defense will present a contractor who used real sealer, offered a refund as soon as {V} complained, and believes damp weather kept the coat from curing. A bad job is a business dispute, not a plan to cheat."),
        closings: ("A coat that washes away with a hose is not driveway sealing, and $700 bought nothing that lasted a day. The drums were mostly water, and the weather does not explain it.", "A thinned coat and a refund offered right away do not add up to a scheme. The State must prove {D} meant to deceive {V}, and a contractor who came back to make it right does not fit that."),
        timeline: [(0, "Morning: the spray."), (1, "The coat washes off.")],
        identified: "Driveway",
        mood: .indifferent)

    static let boosterRaffle = SmallCases.make(
        key: "story.boosterRaffle",
        category: .whiteCollar,
        headlines: ["Booster Club Volunteer Pockets Raffle Cash"],
        law: "embezzlement",
        spec: "Embezzled $620 belonging to {V}, a booster club, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} kept $620 in raffle cash on {DATE} instead of depositing it. The raffle was on a Friday and the deposit was due Monday, but no deposit was made. The ticket stubs total $620.",
        state: [E(.document, 3, "Ticket Stubs", "Stubs total $620; deposit was $0."), E(.document, 2, "Bank Statement", "No deposit from the raffle.")],
        defense: [E(.statement, 1, "Lost Bag", "{DL} says the bag was lost.")],
        role: "Club president",
        exam: [.direct("What happened with the booster club's raffle money?", "\"The raffle was held on a Friday, and the deposit was due Monday. No deposit was ever made. The ticket stubs total $620.\""), .direct("Who was responsible for the cash?", "\"{D}. {D.He} took the raffle money after the event to deposit it. I trusted {D.him} to do that.\""), .direct("What does the bank statement show?", "\"No deposit from the raffle. The stubs show $620 collected, and the bank shows $0 deposited.\""), .direct("How was the raffle run that Friday night?", "\"We sold tickets at the gym entrance for two dollars each or three for five. At the end we drew five winners and counted the stub total at the front table.\""), .direct("What was done with the cash after the drawing?", "\"{D.He} gathered it into a zippered bank bag and agreed to deposit it Monday morning. Two other parents watched the money go into the bag.\""), .direct("When did you learn the deposit was missing?", "\"I checked the account later that week and saw nothing from Friday. I called {D.him}, who said it would be dealt with, and then the story about the bag came out.\""), .cross("{DL} says the bag was lost, doesn't {D.he}?", "\"I can't dispute that bags get lost. But {D.he} didn't tell me at the time.\""), .cross("Did {DL} ever offer to repay the money?", "\"I don't recall an offer. We talked about it afterward, and I made a note. No money has come back.\""), .cross("Did you check on the deposit on Monday?", "\"I looked at the account a few days later. I should have checked sooner. I trusted {D.him}.\""), .cross("The ticket stubs show $620, but you did not count the cash yourself, did you?", "\"The treasurer and I counted the stubs, and the number matched the stub total. The cash count was done at the table by the volunteers, including {DL}.\""), .cross("You never filed a police report about a lost bag, did you?", "\"Nobody did at first. We spent a few days asking around the gym and the parking lot before the board voted to go to the sheriff.\"")],
        theory: ("{D} kept the cash.", "A lost bag."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} bought a game console that week.", "The bag was never reported lost."),
        defendant: [.direct("What happened to the raffle money?", "\"I had it in a bag after the raffle. The bag was lost, and the money went with it. I was sick about it.\""), .direct("Why didn't you tell the club right away?", "\"I was ashamed. I kept thinking I'd find it. I looked in the car, at home, and at the school. It never turned up.\""), .direct("Did you spend the money?", "\"No. I never touched it. I'd never use club money. The bag was lost, and I should have said so immediately.\""), .direct("Where did you take the bag after the raffle?", "\"I carried it to my car and drove straight home. I put it on the passenger seat and meant to take it to the bank after work Monday.\""), .direct("When did you realize it was missing?", "\"On Monday morning the bag was not on the seat or in the trunk. I searched the garage, the car twice, and the gym storage closet.\""), .direct("Why did you stay quiet for several days?", "\"I was embarrassed and kept telling myself it would turn up. I did not want the other parents to think I had been careless with their money.\""), .cross("$620 is a lot to lose, isn't it?", "\"Yes. I know that. I had it in a regular bag and I should have deposited it that night.\""), .cross("You didn't report the bag lost, did you?", "\"No. I told myself I'd find it. I know that makes it sound like I'm covering something.\""), .cross("The deposit was due Monday, wasn't it?", "\"Yes. I knew that. I should have said something before then. I was embarrassed.\""), .cross("You bought a game console that week, didn't you?", "\"Yes, I did, for my kid's birthday. I used my own paycheck and I can show the receipt, and it had nothing to do with the raffle cash.\""), .cross("You never offered to repay the club, did you?", "\"I talked about it but never set a date. I was waiting to see if the bag turned up before I put down a number.\"")],
        openings: ("A booster club raffle raised $620 on a Friday night, and the deposit was due Monday. The bank shows no deposit, the stubs show $620, and the person holding the bag was {D}.", "The defense will present a volunteer who says the bag vanished before the bank opened and who was too ashamed to say so for days. Nobody saw {D} spend the money, and the bag was never found."),
        closings: ("Six hundred twenty dollars in stubs, nothing in the bank, and one volunteer who never reported a loss. A game console bought that same week raises questions the explanation does not answer.", "A lost bag and a volunteer who panicked are not the same as theft. The State has to prove {D} kept the money, and what it has shown is shame, delay, and a purchase with a receipt."),
        timeline: [(0, "Friday: the raffle."), (0, "Monday: no deposit.")],
        identified: "Ticket Stubs",
        mood: .indifferent)

    static let closedHotTub = SmallCases.make(
        key: "story.closedHotTub",
        category: .publicOrder,
        headlines: ["Man Uses Closed Hotel Hot Tub After Hours"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a hotel, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} used a closed hotel hot tub on {DATE} and ignored two staff orders to leave. The hot tub is behind a gate marked for registered guests. The pool closed at 11 p.m., and deputies arrived at 11:40 p.m.",
        state: [E(.video, 3, "Pool Camera", "{D} soaks after the pool closes."), E(.statement, 2, "Night Clerk", "Twice told {D} the pool was closed.")],
        defense: [E(.statement, 1, "Guest", "{DL} says {D.he} was a guest.")],
        role: "Night clerk",
        exam: [.direct("What was the status of the hotel pool on {DATE}?", "\"The pool closed at 11 p.m. The hot tub is behind a gate marked for registered guests, and it was closed after that time.\""), .direct("What did you see {DL} doing?", "\"{D} was soaking in the hot tub after the pool had closed. The pool camera shows {DL} in the water.\""), .direct("What did you do?", "\"I told {D.him} twice that the pool was closed and asked {D.him} to get out. {D.He} stayed in. Deputies arrived at 11:40.\""), .direct("How is the hot tub area marked off?", "\"It sits inside a gated enclosure with a sign saying registered guests only and listing hours until 11 p.m. The gate takes a room key card to open.\""), .direct("When did you first approach {D}?", "\"A few minutes past eleven I walked out and told {DL} the pool was closed. {DL} nodded but stayed put, so I went back inside.\""), .direct("What happened on your second visit?", "\"About fifteen minutes later I returned and asked again, more firmly. {D.He} said the water was relaxing and that {D.he} would leave soon, so I called the sheriff's office.\""), .cross("{DL} says {D.he} was a guest, doesn't {D.he}?", "\"I couldn't confirm that. Guests are welcome until 11, but not after closing.\""), .cross("Did {DL} cause any damage?", "\"No. {D.He} just stayed in the tub. There was no damage, and nobody complained.\""), .cross("Did you check {DL}'s registration?", "\"I asked. {D.He} said {D.he} was a guest, but I couldn't see a room key or confirm it.\""), .cross("Guests often stay a little past closing, don't they?", "\"Sometimes they do, and I usually let it go for a few minutes. This was different because {D.he} twice declined a direct request.\""), .cross("You could not find a room under the defendant's name, could you?", "\"I looked on the screen and could not match the name. That can happen with a shared booking, so I did not rule out that someone had given {DL} access.\"")],
        theory: ("{D} stayed after closing.", "A guest."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had no room key.", "A guest gave {DL} a card."),
        defendant: [.direct("Why were you in the hot tub?", "\"I'm a guest, and I was relaxing after a long day. I didn't think it mattered if I went in a bit after closing.\""), .direct("Did you hear the clerk tell you to leave?", "\"I heard the clerk, yes. I didn't leave right away. I thought it would be fine to stay a few more minutes.\""), .direct("Were you registered at the hotel?", "\"I was a guest. I know I couldn't prove it on the spot. That's why the clerk didn't believe me.\""), .direct("How did you get through the gate?", "\"The gate was latched but not locked, and I pushed it open. I figured nobody would mind since I had been walking around the hotel all evening.\""), .direct("What were you doing in the hot tub?", "\"I was soaking and talking on my phone, trying to unwind after a long drive. I had been in about twenty minutes when the clerk first walked up.\""), .direct("What did you say to the clerk the second time?", "\"I said something like give me five more minutes. It was not polite, and looking back I was being stubborn about it.\""), .cross("The pool closed at 11, didn't it?", "\"Yes. I knew that. I stayed past it anyway. I shouldn't have.\""), .cross("You were told twice to leave, weren't you?", "\"Yes. And I stayed. I was being stubborn. I should have gotten out when asked.\""), .cross("Deputies had to come, didn't they?", "\"Yes. I got out when they came. I was embarrassed. I should have listened earlier.\""), .cross("You never showed a room key to the clerk, did you?", "\"No, I did not have one on me. A friend staying here had given me a card earlier, but I never used it at the gate.\""), .cross("Staff asked you twice and you stayed anyway, correct?", "\"Yes, that is accurate. I should have climbed out the first time and sorted out the rest in the lobby.\"")],
        openings: ("The hotel pool and hot tub closed at 11 p.m., and the gate was marked for registered guests. {D} stayed in the water after two requests from the night clerk, and deputies arrived at 11:40.", "The defense will present someone who believed access came from a friend's card and who caused no damage, no noise complaint, and no harm. {D} climbed out and complied when deputies arrived."),
        closings: ("The clerk asked once, then asked again, and {D} stayed in the water until deputies walked up. A closing time exists so that everyone knows when a pool is off limits.", "A tired traveler stayed too long in a hot tub, damaged nothing, and left when told by deputies. The State must prove more than a stubborn extra half hour."),
        timeline: [(0, "11 p.m.: pool closes."), (0, "11:40 p.m.: deputies arrive.")],
        identified: "Pool Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let boatLakeDWI = SmallCases.make(
        key: "story.boatLakeDWI",
        category: .traffic,
        headlines: ["Boater Arrested for Impaired Operation on Lake"],
        law: "dwi",
        spec: "Operated a vessel while under the influence, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} piloted a boat on {DATE} at .12 with children aboard according to a wildlife officer. The officer approached the boat at 5 p.m. and ran the breath test at 5:20 p.m. The boat was on a busy lake on a weekend.",
        state: [E(.forensic, 3, "Breath Result", "A result of .12."), E(.document, 2, "Officer's Report", "The boat zigzagging near the ramp.")],
        defense: [E(.statement, 1, "Anchored", "{DL} says the boat was anchored.")],
        role: "Wildlife officer",
        exam: [.direct("What did you see on the lake on {DATE}?", "\"A boat zigzagging near the ramp on a busy weekend. I approached the boat at 5 p.m., and {D} was at the helm.\""), .direct("Who was on the boat?", "\"Children were aboard. That's what made me concerned. A boat zigzagging near a ramp with children is a recipe for disaster.\""), .direct("What did the breath test show?", "\"I ran the test at 5:20 and the result was .12. That's well above the .08 limit.\""), .direct("What was the lake like that afternoon?", "\"It was a warm weekend with boats all over the water and a long line at the ramp. The no-wake zone near the ramp was packed with swimmers and kayaks.\""), .direct("What exactly did you observe about the boat's movement?", "\"It swung left, then right, then left again across the channel, closer to a dock than I like to see. Another boater had to throttle back to avoid it.\""), .direct("How did you make contact with {D}?", "\"I pulled alongside with my lights on and signaled for {D.him} to stop. I smelled alcohol when I came within a few feet and asked {D.him} to head to the ramp.\""), .cross("{DL} says the boat was anchored, doesn't {D.he}?", "\"I observed the boat moving in a zigzag near the ramp, and I wrote that in my report.\""), .cross("Was anyone hurt or any boat struck?", "\"No. No one was injured and there was no collision. That's why I stopped it when I did.\""), .cross("The breath test was twenty minutes after you approached, wasn't it?", "\"Yes. It took a few minutes to bring {D.him} in and set up. I can't say the exact level at 5, only that it was .12 at 5:20.\""), .cross("You did not see the boat strike anything, did you?", "\"No, nothing was struck. My concern was the near misses and the children on board, not a collision.\""), .cross("The anchor was visible when you reached the boat, wasn't it?", "\"By the time I reached it the engine was off and I saw a line over the side. I cannot say when that line went down, and I did not see it dropped.\"")],
        theory: ("{D} drove a boat impaired.", "Anchored."),
        allocution: "\"I'm sorry.\"",
        truths: ("The motor was running.", "The anchor was down."),
        defendant: [.direct("What were you doing in the boat that day?", "\"I was out with my family, enjoying the weekend. The boat was anchored when the officer came over, and I was just waiting.\""), .direct("Had you been drinking?", "\"I'd had a few drinks. I wasn't driving the boat when the officer approached. We were anchored and I was relaxing.\""), .direct("Were children on the boat?", "\"Yes. They were my family's kids. I'd never put them in danger. I thought we were safe at anchor.\""), .direct("What was the plan for the afternoon?", "\"We were taking the family out to swim and eat sandwiches. I had a beer with lunch and one more before heading back toward the ramp.\""), .direct("Who was at the helm when the officer arrived?", "\"I was in the driver's seat with my hands near the wheel. The engine had been off a minute, and I think the anchor was down to keep us from drifting.\""), .direct("How did you act with the officer?", "\"I answered every question and did the breath test when asked. I was not rude and I did not try to argue.\""), .cross("The officer says the boat was zigzagging, doesn't the officer?", "\"That's what the officer says. I don't remember it that way. I think we were stationary.\""), .cross("You blew a .12, didn't you?", "\"Yes. That's what the test said. I'm not going to argue the number.\""), .cross("You were at the helm, weren't you?", "\"I was in the seat at the helm. I thought I was just sitting while we were anchored.\""), .cross("The result at 5:20 was .12, wasn't it?", "\"Yes, that is what the machine said. I will not claim it was wrong, only that I was not driving when the officer arrived.\""), .cross("You do not remember the boat zigzagging, do you?", "\"I remember turning around a few times to look at the children and the shoreline. I will not say the officer is lying about what it looked like from the water.\"")],
        openings: ("On a crowded weekend at 5 p.m., a wildlife officer watched a boat zigzag near the ramp with children aboard and stopped it. A breath test twenty minutes later registered .12, and {D} was at the helm.", "The defense will present a boat that was anchored with the motor off when the officer reached it. The State must show {D} was operating it while impaired, not merely sitting aboard a boat at rest."),
        closings: ("A zigzagging boat near the ramp, children aboard, and a .12 on the breath test all point to one driver. A lake is not a place to guess about someone's impairment.", "When the officer reached it, the boat was stopped with an anchor line over the side. The State has to prove {D} was driving it, and an anchored boat is not being piloted."),
        timeline: [(0, "5 p.m.: the stop."), (0, "5:20 p.m.: the test.")],
        identified: "Breath Result",
        mood: .indifferent)

    static let scooterShove = SmallCases.make(
        key: "story.scooterShove",
        category: .violent,
        headlines: ["Scooter Rider Shoves Pedestrian on Sidewalk"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} shoved a pedestrian off the curb on {DATE} after nearly colliding on a sidewalk. The near miss came at 1 p.m. and the shove a minute later. {V} was left with a scrape.",
        state: [E(.video, 3, "Shop Camera", "{D} shoves {V}."), E(.document, 2, "Medical Note", "A scrape from the fall.")],
        defense: [E(.statement, 1, "Block", "{DL} says {V} blocked the sidewalk.")],
        role: "Shopkeeper",
        exam: [.direct("What did you see outside your shop?", "\"At about 1 p.m., {D} nearly collided with {V} on the sidewalk, and a minute later {DL} shoved {V} off the curb.\""), .direct("What does your shop camera show?", "\"{DL} with hands on {V}, and {V} falling to the street. {DL} did not stop.\""), .direct("What was {V}'s injury?", "\"A scrape from the fall. A medical note records it. {V} was not seriously hurt.\""), .direct("How would you describe the sidewalk in front of your shop at 1 p.m.?", "\"It was a lunchtime crowd, with people heading to the corner deli and a few delivery carts in the way. The curb there drops about six inches to the street.\""), .direct("What did you see happen before the shove?", "\"{DL} came fast along the sidewalk and nearly ran into {V}. They stopped face to face and I saw {DL} say something sharp, then {V} said something back.\""), .direct("What did you do after you saw {V} fall?", "\"I ran outside and helped {V} sit up on the curb. {V} had a scraped palm and elbow, and I handed over paper towels from the shop.\""), .cross("Did {V} step into {D}'s path?", "\"It may have looked that way. I did not see the first near miss clearly.\""), .cross("Did the defendant keep going after the shove?", "\"Yes. {D.He} did not stop to help.\""), .cross("Was the sidewalk crowded?", "\"Fairly busy. That is not unusual at that hour.\""), .cross("The near miss happened a minute before the shove, correct?", "\"Yes, about a minute. They spoke in that time, and I could not hear the words through the glass.\""), .cross("{V} was looking at a phone when it started, wasn't {V.he}?", "\"I believe {V.he} was glancing at it. That is common on that stretch, and it might have put {V.him} closer to {DL}'s path.\"")],
        theory: ("{D} shoved a pedestrian.", "A blockage."),
        allocution: "\"I'm sorry.\"",
        truths: ("{V} fell on the curb.", "{V} stepped into {D.his} path."),
        defendant: [.direct("Did you shove {V}?", "\"Yes, I did. We nearly collided on the sidewalk, {V} stepped in front of me, and I shoved to get past.\""), .direct("Why did you shove {V.him}?", "\"I felt blocked and I was in a hurry. I reacted without thinking, and I did not plan to hurt anyone.\""), .direct("Did you stop afterward?", "\"No. I kept going. I did not think {V.he} was hurt, and I did not look back.\""), .direct("What did the sidewalk look like to you?", "\"It was crowded and narrow with a cart blocking half of it. I was trying to get to an appointment and cut through where I could.\""), .direct("What happened in the moment before you shoved?", "\"We nearly collided, and {V.he} snapped at me. I was irritated and pushed with both hands before I thought about the curb behind {V.him}.\""), .direct("Why did you keep walking?", "\"I was embarrassed and in a hurry, and I told myself {V.he} was fine. I did not look back, and I regret that more than the shove.\""), .cross("{V} fell off the curb because of your shove, didn't {V.he}?", "\"I did not mean for that to happen, but I know that is what happened. I feel awful about it.\""), .cross("You left someone on the ground and walked away, didn't you?", "\"I did. I should have stopped and helped. That was wrong, and I feel bad about it.\""), .cross("You could have walked around {V.him}, couldn't you?", "\"Yes, I could have. I wish I had taken a second to step aside instead of pushing.\""), .cross("You pushed with both hands, didn't you?", "\"Yes. It was not an accident that my hands came up, and I am not pretending {V.he} fell on {V.his} own.\""), .cross("You never apologized, did you?", "\"No, I did not. I have thought about it every day since and would apologize now if I could.\"")],
        openings: ("At 1 p.m. {D} nearly collided with {V} on a crowded sidewalk, and a minute later {D} shoved {V} off the curb. The shop camera recorded the push, and {V} was left with a scrape from the fall.", "The defense will present a busy lunchtime sidewalk, a near collision, and a reaction in the heat of the moment. {D} admits the shove, regrets leaving, and says {V} stepped into {D.his} path."),
        closings: ("The shop camera shows two hands on {V}, a fall to the street, and {D} walking away without a word. A near miss on a sidewalk never gives anyone the right to push another person.", "A split second of irritation on a packed sidewalk led to a shove that {D} deeply regrets. The injury was a scrape, and {D} has been honest about every part of it."),
        timeline: [(0, "1 p.m.: the near miss."), (0, "1:01 p.m.: the shove.")],
        identified: "Shop Camera",
        mood: .indifferent)

    static let yogaCubby = SmallCases.make(
        key: "story.yogaCubby",
        category: .property,
        headlines: ["Purse Taken From Yoga Studio Cubby During Class"],
        law: "misdLarceny",
        spec: "Stole property of {V}, valued at $210, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took a purse from a studio cubby on {DATE} while the class was in session. Class started at 6 p.m., and the purse was lifted at 6:10 p.m. The purse was worth $210.",
        state: [E(.video, 3, "Lobby Camera", "{D} lifts a purse from the cubbies."), E(.document, 2, "Purse Receipt", "A $210 receipt for the purse.")],
        defense: [E(.statement, 1, "Own Bag", "{DL} says it looked like {D.his} bag.")],
        role: "Studio owner",
        exam: [.direct("What happened during the evening class?", "\"The class started at 6 p.m. At 6:10, {D} lifted a purse from the cubbies and left by a side door.\""), .direct("What does the lobby camera show?", "\"It shows {DL} lifting the purse from the cubbies. It is clear on the video.\""), .direct("What was the purse worth?", "\"$210. There is a receipt for it.\""), .direct("How does the cubby area work at your studio?", "\"Students leave bags and shoes in wooden cubbies by the lobby door before class. Nobody is posted there once class starts, so we rely on trust and a camera over the door.\""), .direct("How did you find out the purse was missing?", "\"The owner came out after class and could not find it. I pulled the lobby footage, and we saw someone lift it at 6:10 and go out the side door.\""), .direct("What kind of purse was it?", "\"A tan leather shoulder bag with brass fittings, bought new for $210. The owner had the receipt on an email and showed it to me and the deputy.\""), .cross("{D} had a bag in the next cubby, didn't {D.he}?", "\"Yes. {D.his} own bag was in the cubby next to the purse.\""), .cross("The two bags look alike?", "\"They could have looked alike. I do not know exactly how they looked.\""), .cross("Did the defendant try to hide?", "\"{D.He} left by the side door. I do not know why.\""), .cross("The bag next to it was also tan, wasn't it?", "\"Yes, {D.his} bag was in the next cubby and was a similar shade. They are close in size.\""), .cross("{D} took the purse without hurrying, correct?", "\"On the camera {DL} moves calmly, with no looking around. That is consistent with someone who thought it was {D.his} own, though I cannot say what {DL} was thinking.\"")],
        theory: ("{D} took a purse.", "A mix-up."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL}'s own bag was in the next cubby.", "{DL} left by a side door."),
        defendant: [.direct("Did you take the purse?", "\"I took it by mistake. It looked just like mine, and I picked up the wrong bag.\""), .direct("Why did you leave by the side door?", "\"It is a habit. I use that door every time I come and go.\""), .direct("Where was your own bag?", "\"In the next cubby. I did not notice until I got home that I had the wrong one.\""), .direct("What was your own bag like?", "\"It is a tan canvas bag with a leather strap, about the same size. I put it in the next cubby before class like I always do.\""), .direct("What did you notice when you took the purse?", "\"I grabbed it without looking because I was feeling dizzy and wanted to leave. I did not open it or check what was inside until later.\""), .direct("When did you realize it was not yours?", "\"At home I opened it to find my keys and saw someone else's wallet and sunglasses. My stomach sank and I did not know who to call.\""), .cross("You did not return it, did you?", "\"I meant to. I did not know how to reach the owner.\""), .cross("The bags are different, aren't they?", "\"They are similar. I did not look closely.\""), .cross("You left in the middle of class. Why?", "\"I felt sick. I went home early.\""), .cross("You did not call the studio that night, did you?", "\"No. I was nervous and had no number saved, and I planned to bring it back the next morning.\""), .cross("You left in the middle of class and went out a side door, right?", "\"Yes, because the dizziness hit and the side door is closer to where I park. I did not think twice about it.\"")],
        openings: ("During an evening class that began at 6 p.m., {D} lifted a $210 purse from a studio cubby at 6:10 and left by the side door. The lobby camera recorded it, and the purse was not returned.", "The defense will present two similar bags sitting in neighboring cubbies and a student who felt ill and grabbed the wrong one. {D} had {D.his} own bag a few inches away, which is not what a thief leaves behind."),
        closings: ("The lobby camera shows the purse lifted and carried out the side door, and it never came back. Whatever the reason, the owner lost a $210 bag.", "Two similar bags, one dizzy student, and a mistake that came from a rush to leave. The State has to prove {D} meant to take what was not {D.his}, and the bag left in the next cubby says otherwise."),
        timeline: [(0, "6 p.m.: class starts."), (0, "6:10 p.m.: the purse is lifted.")],
        identified: "Lobby Camera",
        mood: .indifferent)

    static let airportPass = SmallCases.make(
        key: "story.airportPass",
        category: .whiteCollar,
        headlines: ["Man Forges Airport Long-Term Parking Pass"],
        law: "forgery",
        spec: "Forged a parking pass of {V}, an airport authority, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} printed fake parking passes on {DATE} and used them for a month of long-term parking. The first pass was used thirty days before the gate flagged the serial. Four passes carry the same serial number.",
        state: [E(.document, 3, "Fake Passes", "Four printed passes with the same serial."), E(.document, 2, "Gate Logs", "Repeated entries on the same serial number.")],
        defense: [E(.statement, 1, "Gift", "{DL} says a friend gave the passes.")],
        role: "Airport parking manager",
        exam: [.direct("What did you discover about the parking passes?", "\"Four printed passes carried the same serial number. The gate logs show repeated entries on that same serial.\""), .direct("How long did this go on?", "\"About a month. The first pass was used thirty days before the gate flagged the serial. It was long-term parking that was never paid for.\""), .direct("How did you tie the passes to {DL}?", "\"The passes were used by {D}'s vehicle. We pulled the logs and found {D.his} plate on every one.\""), .direct("How do the parking passes work at your lot?", "\"Each pass has a unique serial number printed with a barcode that the gate reads on the way in. A serial is meant to be used by one vehicle for a set number of days.\""), .direct("How did you discover the problem?", "\"The gate system flagged the same serial entering again and again. I pulled four printed passes from the booth and found the serial was identical on all of them.\""), .direct("What did the gate logs show about {D}'s vehicle?", "\"The same plate showed up with the duplicate serial almost every day for thirty days. It came in around seven in the morning and left near six at night.\""), .cross("{DL} says a friend gave the passes, doesn't {D.he}?", "\"I can't confirm that. All I know is the passes were fake and {DL}'s car used them.\""), .cross("Could {DL} have known the passes were fake?", "\"They looked real at the gate. A person who got passes from someone else might not have known.\""), .cross("Did {DL} try to hide the car?", "\"No. The car was parked in the lot in the regular way. {D.He} wasn't hiding anything.\""), .cross("You never saw the defendant print a pass, did you?", "\"No. I know the passes were printed, but my information about who printed them comes from the gate logs and the sheriff's follow-up.\""), .cross("The passes looked genuine to a gate attendant, correct?", "\"They looked right at a glance, which is why they worked for a month. It took the system matching serials to catch them.\"")],
        theory: ("{D} forged passes.", "A gift."),
        allocution: "\"I'm sorry.\"",
        truths: ("A printer was found at {DL}'s home.", "The friend is real."),
        defendant: [.direct("Where did you get the passes?", "\"A friend gave them to me. I thought they were legitimate long-term passes. I didn't know anyone printed them.\""), .direct("Did you print them?", "\"No. I didn't make them. I didn't know how, and I wouldn't have. I only used what I was given.\""), .direct("Why did you use the same passes for a month?", "\"I thought they were good for the whole month. They worked every time at the gate. I didn't think about it.\""), .direct("Who gave you the passes?", "\"A friend I knew from work, who said the company had extra passes. I took them and used one a day for a month without thinking more of it.\""), .direct("Where did you keep them?", "\"In my glove compartment with the registration. I never hid them, and I handed them to the gate attendant in plain view.\""), .direct("What happened when the lot manager contacted you?", "\"I was told the serial numbers matched and that the passes were not real. I told the manager the same thing I am telling you, that I did not make them.\""), .cross("Four passes with the same serial, weren't there?", "\"I've heard that. I didn't look at the serials. I just used them as I was told.\""), .cross("You can't name your friend, can you?", "\"I can, but I'd rather not. I know it makes it worse. I'm not trying to hide anything else.\""), .cross("You parked for free for a month, didn't you?", "\"Yes. I know that's a lot of parking. I didn't know it was supposed to be paid for.\""), .cross("The same serial appeared on all four passes, correct?", "\"So I was told. I never looked at the numbers, and I trusted the person who gave them to me.\""), .cross("A printer was found in your home, wasn't it?", "\"Yes, I have a regular printer for school work. I have never printed a parking pass on it.\"")],
        openings: ("Four printed parking passes with the same serial number carried a vehicle into long-term airport parking for a month. The gate logs show {D}'s plate every day, and a printer was found at {D}'s home.", "The defense will present a person who received the passes from a friend and used them openly in a car plated in {D.his} own name. {D} did not print them and did not know they were fakes."),
        closings: ("Four passes, one serial, thirty days of free parking, and {D}'s plate on every entry. Common sense tells you that someone knew the passes were not real.", "A person who truly makes fake passes does not hand them to the attendant in plain sight. {D} was given them by a friend, and the State has not proved otherwise."),
        timeline: [(-30, "First use."), (0, "The gate flags the serial.")],
        identified: "Fake Passes",
        mood: .indifferent,
        genders: ["D": .male])

    static let fakeSickNote = SmallCases.make(
        key: "story.fakeSickNote",
        category: .whiteCollar,
        headlines: ["Employee Hands Boss Forged Doctor's Note"],
        law: "uttering",
        spec: "Uttered a forged doctor's note to {V}, an employer, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} gave an employer a forged doctor's note on {DATE} to cover a week off. {D} turned in the note on a Monday, and the plant manager called the clinic on Tuesday. The note covered a week off.",
        state: [E(.document, 3, "Doctor's Note", "The doctor says {D} was never a patient."), E(.document, 2, "Clinic Response", "The clinic has no record of {D}.")],
        defense: [E(.statement, 1, "Sick", "{DL} says {D.he} really was sick.")],
        role: "Plant manager",
        exam: [.direct("What did {DL} give you on Monday?", "\"A doctor's note to cover a week off from the plant. {D} turned it in on a Monday.\""), .direct("What did you do about it?", "\"On Tuesday, I called the clinic to verify it. I do that when a note covers a whole week.\""), .direct("What did the clinic tell you?", "\"The clinic has no record of {DL}. The doctor named on the note says {DL} was never a patient.\""), .direct("What did the note look like?", "\"It was a half sheet with a clinic letterhead, a doctor's printed name, and a signature. It said {D.he} needed seven days of rest and listed dates from Monday through the following Sunday.\""), .direct("What made you call the clinic?", "\"The doctor's name looked off and the letterhead had a blurry logo. On Tuesday morning I called the number printed on it to confirm the dates.\""), .direct("What did {D} say when you brought it up?", "\"{D.He} lowered {D.his} eyes and said, I can explain. I asked for time to review it with human resources and told {D.him} to wait in the break room.\""), .cross("{DL} says {D.he} really was sick, doesn't {D.he}?", "\"I can't dispute being sick. But the note was not from a doctor who saw {D.him}.\""), .cross("Did {DL} work well otherwise?", "\"Generally yes. {DL} was a decent worker. That's why this was a surprise to me.\""), .cross("Did {DL} lose pay or benefits because of the note?", "\"The note covered a week off. I can't say what {D.he} would have lost without it. I only know it was submitted to me.\""), .cross("{D} had no earlier discipline problems, correct?", "\"Not that I recall. {D.his} attendance was good until this, and I had no reason to suspect anything.\""), .cross("You never saw anyone at the clinic confirm {D} was sick, did you?", "\"No. I only know that the clinic had no record of a visit, so I cannot say whether {D.he} was ill or saw a different doctor.\"")],
        theory: ("{D} forged a note.", "Real illness."),
        allocution: "\"I'm sorry.\"",
        truths: ("The clinic has no record.", "A pharmacy slip shows medicine bought that week."),
        defendant: [.direct("Why did you give the plant a note?", "\"I was sick and I needed the week off. I thought I needed a doctor's note, and I didn't have one.\""), .direct("Where did the note come from?", "\"I made it. I wasn't able to see a doctor in time. I was worried I'd lose my job, and I panicked.\""), .direct("Were you really sick?", "\"Yes. I was sick that week. I wasn't lying about being ill, but I did something I shouldn't have to cover it.\""), .direct("How were you feeling that week?", "\"I had a fever and terrible chest congestion. I stayed in bed most of the week and took cold medicine from the drugstore.\""), .direct("Why did you not just see a doctor?", "\"I had no insurance and could not afford the visit fee. I was also afraid that if I missed a week with no note the plant would let me go.\""), .direct("How did you make the note?", "\"I used a template from the internet and typed in a doctor's name from an old bill. I printed it on a library printer and signed it myself.\""), .cross("The clinic has no record of you, does it?", "\"No. I wasn't a patient there. I know that proves the note wasn't real.\""), .cross("You handed in a forged note, didn't you?", "\"Yes. I did. I'm ashamed of it. I should have talked to my manager instead.\""), .cross("The doctor on the note says you were never a patient, doesn't the doctor?", "\"Yes. The doctor's name was on the note and I had no right to use it.\""), .cross("You knew the note was forged when you handed it in, didn't you?", "\"Yes, I knew. I told myself it was harmless because I really was sick, but that is not an excuse.\""), .cross("You picked a real doctor's name, didn't you?", "\"It was a name I saw on a bill, and I did not stop to think about using another person's name. I regret that part most.\"")],
        openings: ("On a Monday {D} handed the plant a doctor's note to cover a week off, and on Tuesday the plant manager called the clinic. The clinic had no record of {D}, and the doctor said {D} was never a patient.", "The defense will present a worker who really was sick, had no insurance, and panicked about losing a job. A pharmacy slip shows {D} bought medicine that same week."),
        closings: ("A note with a real doctor's name, a clinic with no record, and a doctor who never saw {D} add up to a forged document. Being sick does not excuse writing a lie on someone else's letterhead.", "{D} was ill, scared, and made a poor choice to protect a job. The pharmacy slip supports the illness, and the State must prove {D} meant to deceive, not just that the note was false."),
        timeline: [(0, "Monday: the note."), (0, "Tuesday: the call to the clinic.")],
        identified: "Doctor's Note",
        mood: .indifferent)

    static let bakeSaleBox = SmallCases.make(
        key: "story.bakeSaleBox",
        category: .property,
        headlines: ["Cash Box From School Bake Sale Taken"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a parent group, valued at $340, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took a cash box from a school bake sale table on {DATE}. The sale ran at noon, and the box vanished at about 12:30 p.m. The box held $340.",
        state: [E(.video, 3, "Hallway Camera", "{D} walks off with a box."), E(.statement, 2, "Parent Volunteer", "The box was on the table until about 12:30 p.m.")],
        defense: [E(.statement, 1, "Volunteer", "{DL} says {D.he} was moving it for safekeeping.")],
        role: "Parent volunteer",
        exam: [.direct("What was happening at the school's bake sale at noon on {DATE}?", "\"We had a table set up in the hallway with a cash box. The sale ran at noon, and the box was on the table until about 12:30.\""), .direct("What happened to the box?", "\"It vanished at about 12:30. It held $340. I turned around and it was gone.\""), .direct("What does the hallway camera show?", "\"It shows {D} walking off with a box. You can see {DL} pick it up and carry it down the hall.\""), .direct("How was the bake sale table arranged?", "\"Four of us staffed a folding table in the main hallway, with trays of cookies and cupcakes in front and a gray metal cash box at the back corner. We kept it closed except to make change.\""), .direct("When did you last see the box?", "\"I made change from it around 12:25 for a customer buying brownies. A few minutes later I turned to wrap a cake and when I looked back the box was gone.\""), .direct("What did you do when you noticed?", "\"I asked the other volunteers if anyone had moved it, and nobody had. I walked down the hall to the office, and the principal pulled up the camera.\""), .cross("{DL} says {D.he} was moving it for safekeeping, doesn't {D.he}?", "\"I never asked anyone to move it. If someone wanted to keep it safe, they would've told us.\""), .cross("Is {DL} a volunteer?", "\"Yes, {DL} was volunteering that day. That's why I didn't think twice about {DL} being near the table.\""), .cross("Did you see {DL} take the box?", "\"No. I was helping a customer. I only know about it from the camera and from when I noticed it was gone.\""), .cross("The box was not locked, was it?", "\"It had a small latch but no lock. It sat out in the open at the corner of the table, which I realize was not ideal.\""), .cross("{D} had been working the table earlier that day, hadn't {D.he}?", "\"Yes, {D.he} did a shift from eleven to noon. After that {D.he} was around the hall, though I did not know {D.he} was still part of the sale.\"")],
        theory: ("{D} took the box.", "Safekeeping."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} left the building.", "{DL} was a volunteer."),
        defendant: [.direct("Why did you pick up the cash box?", "\"I was a volunteer. I thought it would be safer in a back room. I wanted to keep the cash secure.\""), .direct("Did you tell anyone?", "\"No. I own that. I was about to, and then I got distracted. I didn't mean to take it away from the table for long.\""), .direct("Did you intend to steal the money?", "\"No. I'm a volunteer. I'd never steal from a school. I was only trying to protect it.\""), .direct("What were you doing in the hall that day?", "\"I had finished my volunteer shift and was walking back to the cafeteria. I noticed the cash box sitting at the very edge of the table with nobody watching it.\""), .direct("What did you plan to do with the box?", "\"I was going to take it to the school office and lock it in the safe until the sale ended. I thought that was the responsible thing to do.\""), .direct("Where did you go after the hallway?", "\"I walked outside to my car first because I had to grab my purse for the office key card. I was gone only a few minutes, and I planned to come right back.\""), .cross("The box held $340, didn't it?", "\"I didn't count. I picked it up and took it with me. I know that sounds bad.\""), .cross("You didn't ask anyone before moving it, did you?", "\"No. That is on me. I thought I was helping. I didn't think anyone would mind.\""), .cross("You walked down the hall with it, didn't you?", "\"Yes, the camera shows it. I wasn't hiding. I was going to a back room.\""), .cross("You left the building with the money, correct?", "\"Yes, I stepped out the side door to my car. I can see how that looks, and that is why I wish I had told someone before I picked it up.\""), .cross("Nobody told you to move it, did they?", "\"No. It was my own idea, and I should have asked a volunteer at the table first.\"")],
        openings: ("At a school bake sale, a cash box holding $340 vanished from the table at about 12:30 p.m. The hallway camera shows {D} carrying a box away, and nobody had asked {D} to move it.", "The defense will point to a fellow volunteer who thought the box was sitting unattended and meant to lock it in the office safe. {D} walked openly down a busy hallway, hiding nothing, and never meant to keep a cent."),
        closings: ("A $340 box was on the table at 12:25 and gone by 12:30, and the camera shows {D} walking off with it. {D} did not ask anyone and left the building, which is hard to square with safekeeping.", "{D} was a volunteer who moved a cash box in plain view down a busy hallway. The State has not proved an intent to steal, only a well-meant act that was poorly explained."),
        timeline: [(0, "Noon: the sale."), (0, "12:30 p.m.: the box vanishes.")],
        identified: "Hallway Camera",
        mood: .indifferent)

    static let motelTv = SmallCases.make(
        key: "story.motelTv",
        category: .property,
        headlines: ["Guest Walks Out of Motel With Room TV and Lamp"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a motel, valued at $520, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} left a motel with the TV and a lamp on {DATE}. {D} checked out and the TV and a lamp were missing afterward. They were worth $520.",
        state: [E(.video, 3, "Lobby Camera", "{D} carries a TV to a car."), E(.document, 2, "Room Inventory", "A TV and a lamp listed for the room.")],
        defense: [E(.statement, 1, "Moved", "{DL} says staff told {D.him} to take them.")],
        role: "Motel clerk",
        exam: [.direct("What was missing after {D} checked out?", "\"A TV and a lamp from the room. Together they are worth about $520.\""), .direct("What does the lobby camera show?", "\"It shows {D} carrying a TV out to a car. It is clear.\""), .direct("Does the room inventory list those items?", "\"Yes. A TV and a lamp are listed for that room.\""), .direct("How does a guest check out at your motel?", "\"The guest returns the key card to the front desk and I check the room by walking through it with a housekeeper. We compare what is there with the inventory sheet for that room.\""), .direct("What did you find when you inspected the room?", "\"The mounting bracket on the wall was empty and the bedside lamp was gone. The cord ends were still plugged into the outlet.\""), .direct("How did you learn who took them?", "\"I pulled the lobby footage from that morning. It shows {DL} carrying a flat screen TV across the lobby, with a lamp under one arm, to a car at the curb.\""), .cross("Did the defendant say someone told {D.him} to take them?", "\"Yes. {DL} said someone at the desk said it was fine. I do not know of any such instruction.\""), .cross("Was the TV returned later?", "\"Yes, the TV was returned later. I will say that.\""), .cross("Did the defendant check out properly?", "\"Yes. {D.He} checked out at the desk in the normal way.\""), .cross("{D} did not run, did {D.he}?", "\"No. {DL} walked out at a normal pace and said good morning to me at the desk. That is part of why I did not stop {DL} right then.\""), .cross("The motel was running a promotion that week, wasn't it?", "\"We had a discount on weekend rates, but nothing about giving away items from rooms. Nobody on staff is authorized to hand out a TV.\"")],
        theory: ("{D} took room items.", "Staff said so."),
        allocution: "\"I'm sorry.\"",
        truths: ("No such instruction exists.", "The TV was returned later."),
        defendant: [.direct("Did you take the TV and the lamp?", "\"Yes, I did. But I thought I was allowed to. Someone at the desk said I could.\""), .direct("Who told you that?", "\"Someone at the desk. I do not remember who it was.\""), .direct("What did you do with the TV?", "\"I took it home. Later I returned it.\""), .direct("What did the person at the desk say to you?", "\"I asked what to do about a broken remote and was told, you might as well take it, we are replacing everything in those rooms. I took that to mean the TV and lamp were being cleared out.\""), .direct("How did you feel when you walked out with them?", "\"Easy. The clerk had smiled and nodded, and I carried them across the lobby in plain view without any worry.\""), .direct("Why did you return the TV?", "\"After a few days I read about the motel's reports and felt uncomfortable. I drove back and left the TV at the front desk with a note.\""), .cross("Who at the desk told you?", "\"I do not remember the name. It was a busy morning.\""), .cross("A TV and a lamp do not leave motels as gifts, do they?", "\"I understood there was a promotion. I should have checked.\""), .cross("You carried it out in front of a camera. Did you try to hide it?", "\"No. I carried it out in the open. I did not think I was doing wrong.\""), .cross("You never got anything in writing, did you?", "\"No, it was verbal, and I now know I should have gotten a receipt or a name.\""), .cross("The lamp was not returned, was it?", "\"It was not. I had thrown it away because the shade was cracked, and I should have said that when I returned the TV.\"")],
        openings: ("{D} checked out of a motel and walked through the lobby carrying a TV and a lamp worth $520. The lobby camera recorded it, and the room inventory lists both items.", "Jurors will hear that {D} believed a worker at the front desk said the items could be taken, carried them in the open, and returned the TV days later. {D} had no reason to hide anything."),
        closings: ("A TV and a lamp left the motel through the lobby, and nobody at the desk had authority to give them away. The room inventory and the camera make plain what was taken.", "{D} carried the items out in the open, believed what a desk worker said, and brought back the TV on {D.his} own. That is not the conduct of someone planning to steal."),
        timeline: [(0, "Checkout."), (0, "The TV is missing.")],
        identified: "Lobby Camera",
        mood: .indifferent)

    static let karaokeMic = SmallCases.make(
        key: "story.karaokeMic",
        category: .publicOrder,
        headlines: ["Man Throws Microphone and Screams at Karaoke Night"],
        law: "disorderly",
        spec: "Disturbed the peace of {V}, a bar, by violent conduct, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} threw a microphone and screamed at the host on {DATE} when denied a song slot. The slot was denied at 10 p.m., and the mic was thrown five minutes later. The bar has a small stage with a host.",
        state: [E(.video, 3, "Bar Camera", "{D} throws a mic."), E(.statement, 2, "Bar Host", "Heard {D} scream and saw the mic thrown.")],
        defense: [E(.statement, 1, "Drunk", "{DL} says {D.he} was drunk.")],
        role: "Bar owner",
        exam: [.direct("What happened at your bar at 10 p.m. on {DATE}?", "\"{D} asked for a karaoke slot and was denied. About five minutes later, {D.he} threw a microphone and screamed at the host.\""), .direct("What does the bar camera show?", "\"It shows {DL} throwing the mic. It shows the throw and the host stepping back, and the mic hitting the floor.\""), .direct("What did your host tell you?", "\"The host heard {DL} scream and saw the mic thrown. Our host is a small person, and the whole thing frightened the host.\""), .direct("How does karaoke night work at your bar?", "\"We have a small stage and a host with a binder of song requests. Singers sign up in order, and the host cuts off new slots when the list is full.\""), .direct("What did {D} do when told no?", "\"{DL} argued with the host at the stage, raising {D.his} voice, then went back to the bar and ordered another drink. A few minutes later {DL} came back to the stage area and grabbed a mic.\""), .direct("What exactly happened with the mic?", "\"{D.He} screamed at the host and flung the mic across the stage. It slid into the speaker stack and cracked the housing.\""), .cross("{DL} says {D.he} was drunk, doesn't {D.he}?", "\"I can't say how much {DL} had. It doesn't excuse throwing a mic at the host.\""), .cross("Was anyone hit by the microphone?", "\"No. It landed on the floor. Nobody was struck, though it could have hit someone.\""), .cross("Was the mic damaged?", "\"Yes, it needed to be repaired. I don't remember the exact cost. It wasn't expensive, but it was ours.\""), .cross("You did serve the defendant that night, didn't you?", "\"Yes, we did. {D.He} had two drinks before I saw any sign of trouble, and my bartender served a third after the argument.\""), .cross("The host told the defendant to leave twice, didn't the host?", "\"The host said it once at the stage and I said it again at the door. {D.He} did leave, but only on the second request.\"")],
        theory: ("{D} disturbed the bar.", "Drunk."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} was told to leave twice.", "The bar served {D.him}."),
        defendant: [.direct("Why did you throw the microphone?", "\"I'd had too much to drink and I was upset about being denied a song. I lost my temper and threw it.\""), .direct("Did you mean to hit anyone?", "\"No. I wasn't aiming at the host. I just threw it. I wouldn't have wanted to hurt anyone.\""), .direct("How has this affected you?", "\"Ashamed. I was drunk, and I acted like a fool. I'm sorry to the host and to everyone in the bar.\""), .direct("How much had you had to drink?", "\"Probably four or five over a couple of hours. I was not driving, but I was well past where I should have stopped.\""), .direct("What happened when you were told no?", "\"I took it as a slight. I had practiced a song all week, and being turned away in front of friends hurt my pride.\""), .direct("What did you do after the mic left your hand?", "\"I froze. Then I realized it had hit the speaker, so I walked outside to cool off before anyone had to ask me.\""), .cross("You screamed at the host, didn't you?", "\"Yes, I did. I was out of control. I shouldn't have.\""), .cross("You were denied a song slot, weren't you?", "\"Yes, and I took it badly. It's a silly thing to get upset about, and I knew it.\""), .cross("The mic was thrown five minutes after the denial, wasn't it?", "\"Yes. I stewed for a few minutes, and then it came out. I wish I'd walked away.\""), .cross("You were told to leave twice, weren't you?", "\"Yes, once by the host and once by the owner. I did not move until the second time, and that was wrong.\""), .cross("You are responsible for the repair bill, aren't you?", "\"I am. I will pay for the speaker housing and the mic, and I owe the host an apology as well.\"")],
        openings: ("At a bar's karaoke night, {D} was denied a song slot at 10 p.m. and five minutes later screamed at the host and threw a microphone. The bar camera shows the throw, and the host heard every word.", "Jurors will see an intoxicated customer who lost {D.his} temper over a song slot, hit no one, and left when asked. {D} is ashamed and willing to pay for the damage."),
        closings: ("A denied song, a scream, and a microphone sent flying across a stage with a full crowd looking on. The camera shows it, and the bar served {D} that night, but drinking is not a license to throw things.", "Drunk and embarrassed, {D} threw a microphone at nothing in particular and struck no one. The harm is a cracked speaker and a bruised host, and {D} has accepted responsibility."),
        timeline: [(0, "10 p.m.: the song is denied."), (0, "10:05 p.m.: the mic.")],
        identified: "Bar Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let hydrantFlood = SmallCases.make(
        key: "story.hydrantFlood",
        category: .property,
        headlines: ["Man Opens Fire Hydrant and Floods Street"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a town, causing damage of $1,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} opened a fire hydrant with a wrench on {DATE} and flooded a street for an hour. {D} opened it at 3 p.m., and crews arrived at 4 p.m. The hydrant is on a residential street.",
        state: [E(.video, 3, "Street Camera", "{D} turns the hydrant valve."), E(.document, 2, "Water Department Log", "The hydrant opened at 3 p.m. and shut at 4 p.m.")],
        defense: [E(.statement, 1, "Heat", "{DL} says it was a hot day.")],
        role: "Public works supervisor",
        exam: [.direct("What did you learn about the hydrant on {DATE}?", "\"At 3 p.m. a hydrant on a residential street was opened. The water department log shows it opened at 3 and shut at 4.\""), .direct("What does the street camera show?", "\"It shows {D} turning the hydrant valve with a wrench. The video shows it opened and the water pouring into the street.\""), .direct("What was the result?", "\"A street flooded for an hour. Crews arrived at 4 and shut it off. The residents were disrupted, and a lot of water was wasted.\""), .direct("What does a hydrant opening like this do to the system?", "\"It drops water pressure for the whole block and can pull sediment into the lines. It also puts thousands of gallons on the street and into storm drains.\""), .direct("How did the department learn about it?", "\"A neighbor called the non-emergency line at about 3:05 p.m. A crew was dispatched, and I arrived with them a little before four.\""), .direct("What condition was the hydrant in when you got there?", "\"The valve was open full, and the nut on top was rounded off. We had to use a special tool to shut it down.\""), .cross("{DL} says it was a hot day, doesn't {D.he}?", "\"People do open hydrants in the heat, but it's illegal and dangerous. It can also drop water pressure.\""), .cross("Was anyone injured or property damaged?", "\"Nothing serious that I recall. Water ran down the street and into drains. There was some flooding of the roadway.\""), .cross("How did you identify {DL}?", "\"From the street camera, and from neighbors. The wrench and the face were both visible in the video.\""), .cross("The hydrant was not damaged beyond the valve, was it?", "\"The valve stem needed to be replaced, but the barrel and the connection were fine. That repair was done the following week.\""), .cross("Neighbors told you the children were cooling off in the water, didn't they?", "\"Some mentioned it. I did not see any children myself, and nothing in our records shows anyone getting hurt.\"")],
        theory: ("{D} opened a hydrant.", "Heat."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} used a hydrant wrench.", "The valve stripped."),
        defendant: [.direct("Why did you open the hydrant?", "\"It was a very hot day. A lot of people in the neighborhood do it to cool off. I didn't think it would cause harm.\""), .direct("Did you know it was illegal?", "\"I knew it wasn't a good idea. I didn't know it could flood the street for an hour. I figured it would be quick.\""), .direct("What did you do when you saw the flooding?", "\"I tried to close it, but I couldn't. I didn't leave. I stayed until the crews came.\""), .direct("What was the weather that day?", "\"It was ninety-six degrees with no breeze. The street was baking and the kids on the block had nowhere to go.\""), .direct("How did you open the hydrant?", "\"I had a hydrant wrench I kept in my truck, and I turned the valve about three turns. Water shot out far more strongly than I expected.\""), .direct("What happened when you tried to shut it?", "\"The nut stripped and the wrench just spun. I tried for a few minutes, then called the city and waited for the crew.\""), .cross("You used a wrench to open it, didn't you?", "\"Yes. I had one. I know that makes it look planned. I just wanted to cool off.\""), .cross("It ran for an hour, didn't it?", "\"Yes. I wasn't able to stop it. I feel terrible about it.\""), .cross("The hydrant is for fire crews, isn't it?", "\"Yes. I know that. It's not a toy. I shouldn't have touched it.\""), .cross("You took the wrench out of your truck for this, didn't you?", "\"Yes. I did not take it out for any other reason, and I should have known better.\""), .cross("The water ran for a full hour, correct?", "\"Yes. It ran from three until the crew shut it at four, and it flooded the low end of the street.\"")],
        openings: ("On a hot afternoon at 3 p.m., {D} opened a fire hydrant on a residential street with a wrench. The water ran for an hour before a city crew arrived, and the street camera shows {D} turning the valve.", "The defense will present a ninety-degree day, a person who wanted to cool the block, and a valve that stripped and would not close. {D} stayed at the scene and called the city."),
        closings: ("A wrench, a hydrant, and a flooded street for a full hour. The camera shows {D} open the valve, and the water log shows how long it ran.", "A hot day and a thoughtless act, and {D} never meant to flood the street. {D} stayed, tried to close it, and called the city, which is how a person acts who realizes the mistake."),
        timeline: [(0, "3 p.m.: the wrench."), (0, "4 p.m.: crews arrive.")],
        identified: "Street Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let skateRamp = SmallCases.make(
        key: "story.skateRamp",
        category: .publicOrder,
        headlines: ["Skaters Ignore Closure Signs and Break Park Ramp"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a town park, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} skated a closed ramp on {DATE} and cracked a board. The ramp had been closed earlier that afternoon, with a fence across its entrance. The board cracked at about 4 p.m.",
        state: [E(.video, 3, "Park Camera", "{D} skates past the closure fence."), E(.document, 2, "Closure Notice", "The ramp was posted closed that afternoon.")],
        defense: [E(.statement, 1, "No Signs", "{DL} says no signs were visible.")],
        role: "Park ranger",
        exam: [.direct("Was the ramp open that afternoon?", "\"No. It had been closed earlier that afternoon, with a fence across its entrance. A closure notice was posted.\""), .direct("What does the park camera show?", "\"It shows {D} skating past the closure fence and onto the ramp. A board cracked about 4 p.m.\""), .direct("Were signs posted?", "\"Signs were zip-tied to the fence. One may have fallen down, which I noticed later.\""), .direct("What was the status of the ramp that afternoon?", "\"Our crew closed it earlier in the afternoon to repair a cracked coping. We stretched a plastic fence across the entrance and zip-tied three closure signs to it.\""), .direct("How did you find out someone was using it?", "\"A bystander called the front desk about four o'clock. I checked the park camera and saw {DL} rolling around the fence and into the bowl.\""), .direct("What did {D} do when you approached?", "\"{D.He} sat on the lip of the ramp holding a cracked board and said it had just snapped. I walked {D.him} out to the gate and explained the closure.\""), .cross("Did the defendant go through the fence?", "\"The camera shows {DL} going around the fence, not through it.\""), .cross("Could the defendant have missed the signs?", "\"It is possible, if one had fallen. I cannot say.\""), .cross("Was anything damaged besides the defendant's board?", "\"No. The ramp was not damaged.\""), .cross("The closure fence stood at the entrance only, correct?", "\"Yes, the fence covered the main entrance. There is a gap at the side by the bike rack, where {D.he} came around.\""), .cross("You could not say how many signs were still hanging at 4 p.m., could you?", "\"I know three went up. I cannot tell you for certain that all three were still there when {D.he} arrived.\"")],
        theory: ("{D} used a closed ramp.", "No signs."),
        allocution: "\"I'm sorry.\"",
        truths: ("Signs were zip-tied to the fence.", "One sign had fallen."),
        defendant: [.direct("Did you skate the ramp?", "\"Yes, I did. I did not know it was closed, and I rode it the way I would any other day.\""), .direct("Did you see any signs on the fence?", "\"No. I did not see any signs on the fence, and I went around it without thinking about it.\""), .direct("How did you get onto the ramp?", "\"I walked around the fence, not through it. There was a gap on the side that looked open to me.\""), .direct("How did you usually use that park?", "\"I skate there twice a week, usually after school. I know the ramp well and had skated it the weekend before.\""), .direct("What did you see as you approached the ramp?", "\"A plastic fence across the front, and I thought it was some paint crew's equipment. I walked past the bike rack, checked the coping with my hand, and rolled in.\""), .direct("What happened to your board?", "\"I dropped in and landed the first run, then caught a crack in the surface on the second. The board snapped under my front foot.\""), .cross("A fence across the entrance. Wasn't that a clue it was closed?", "\"I thought it was part of some construction. I did not read it as a closure at the time.\""), .cross("You cracked your board on the ramp. Were you hurt?", "\"No, just the board. I was lucky, and I know the ramp may have been closed for safety.\""), .cross("Would you have skated it if you had known it was closed?", "\"No, I would have gone somewhere else. I did not want to break any rules or cause trouble.\""), .cross("You did go around the fence, didn't you?", "\"Yes, around the side. I did not think of it as going past a closure because I did not see a sign.\""), .cross("Fencing is usually a sign that something is wrong, isn't it?", "\"It usually is. I should have asked someone, and I will not claim I was paying attention.\"")],
        openings: ("The skate ramp had been closed that afternoon, with a fence across its entrance and signs zip-tied to it. The park camera shows {D} skating around the fence and onto the ramp, where a board cracked at about 4 p.m.", "Jurors will learn that one closure sign had fallen, that {D} entered from the open side, and that {D} saw nothing telling skaters to stay out. {D} was not hiding and did no damage to the ramp."),
        closings: ("A fence across the entrance and signs zip-tied to it. The camera shows {D} skating past, and the ramp was closed for a reason.", "One sign had fallen, the side was open, and {D} thought it was a work crew's equipment. The State must prove {D} knew the ramp was closed, and the evidence leaves real doubt."),
        timeline: [(0, "Afternoon: the closure."), (0, "4 p.m.: the crack.")],
        identified: "Park Camera",
        mood: .indifferent)

    static let schoolLoiter = SmallCases.make(
        key: "story.schoolLoiter",
        category: .publicOrder,
        headlines: ["Man Loiters at Elementary School After Warning"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a school, after being notified not to, on {DATE}.",
        ages: 18...60,
