        spec: "Possessed a Schedule II controlled substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} had eight unlabeled oxycodone pills in a pharmacy lot on {DATE}. The stop came in the evening. The search followed ten minutes later in the lot.",
        state: [E(.forensic, 3, "Lab Report", "Eight tablets of oxycodone."), E(.document, 2, "Evidence Photo", "Eight unlabeled tablets taken from a pocket.")],
        defense: [E(.statement, 1, "Friend's", "{DL} says a friend asked {D.him} to hold them.")],
        role: "Deputy",
        exam: [.direct("What did you find during the stop?", "\"In the evening, I stopped {D} in a pharmacy lot. About ten minutes later, in the lot, I searched and found eight unlabeled pills in a pocket.\""), .direct("What were the pills?", "\"The lab report says eight tablets of oxycodone. They had no label, no bottle, and no prescription markings of any kind.\""), .direct("What did {D} say about the pills?", "\"{DL} said they belonged to a friend and that {DL} was holding them for the friend. {DL} did not have a prescription.\""), .direct("Where did the stop take place?", "\"In the lot of a pharmacy on a busy road. I saw {DL} sitting in a parked car with the engine off and approached after noticing a taillight out.\""), .direct("Where exactly were the pills found?", "\"In the front right pocket of {D.his} jacket, loose in a plastic sandwich bag. There was no pharmacy label and no pill bottle.\""), .direct("How did you identify the tablets?", "\"I read the stamped markings on them and sent them to the lab. The report confirms eight oxycodone tablets, with the same imprint on each.\""), .cross("{D} did not hide the pills, did {D.he}?", "\"No. {DL} told me about them when I asked. I will say that {DL} was straightforward.\""), .cross("Did you find any scale or cash on {D}?", "\"No. I did not find a scale, bags, or a roll of cash. It was just the eight tablets.\""), .cross("Can you say the pills were meant for sale?", "\"No. I cannot say that from what I found. Eight pills alone does not prove that.\""), .cross("{D} told you where the pills were without being asked, didn't {D.he}?", "\"{D.He} mentioned that there were pills in a pocket before I started any search. I did not have to dig for them.\""), .cross("You did not find any cash or notes about sales, did you?", "\"No. There was a wallet with a few dollars and a phone, and nothing that pointed to selling.\"")],
        theory: ("{D} had pills.", "A friend's."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had no prescription.", "A friend texted about picking them up."),
        defendant: [.direct("Were the pills yours?", "\"They were not mine. I was holding them for a friend who asked me to pick them up near the pharmacy.\""), .direct("Do you have a prescription for oxycodone?", "\"No. I do not. I never claimed to, and I did not take any of them.\""), .direct("Who asked you to hold the pills?", "\"A friend. I got a text asking me to pick them up, and I did, thinking it was a favor.\""), .direct("How did you come to hold these pills?", "\"A friend asked me by text to hold them while the friend dealt with a family emergency. I stopped by on my way to the pharmacy for my own prescription.\""), .direct("Why had you not given them back?", "\"The friend did not answer when I texted the pickup time. I kept them in my pocket until we could meet.\""), .direct("What did you say to the deputy?", "\"I told the deputy right away that they were not mine, that I did not have a prescription, and what the friend had asked. I did not try to hide them.\""), .cross("You were carrying eight oxycodone pills without a prescription, weren't you?", "\"Yes. I know I should not have been. I did not think about what it meant.\""), .cross("Why did you not tell your friend no?", "\"I did not want to let the friend down. I was trying to help, and it was a mistake.\""), .cross("You cannot show that text to the jury, can you?", "\"I have a record of it. I understand it is just a text, and it does not prove the whole story.\""), .cross("You knew oxycodone was a controlled drug, didn't you?", "\"Yes, and that is why I should have refused. Holding them for a friend seemed like a small favor at the time.\""), .cross("You have no prescription, correct?", "\"Correct. I never claimed otherwise, and I do not take those pills myself.\"")],
        openings: ("In a pharmacy lot in the evening, a deputy stopped {D} and found eight unlabeled oxycodone tablets in a jacket pocket. {D} has no prescription, and the lab confirmed the drug.", "The defense will present evidence that {D} was holding the pills as a favor to a friend, hid nothing, and told the deputy the whole story at once. The pills were never for sale."),
        closings: ("Eight oxycodone tablets in {D}'s pocket, with no label and no prescription. A person who carries a controlled drug carries the responsibility for it.", "{D} told the deputy everything, held the pills as a favor, and had no scale, bags, or cash. The State has not proved a possession that was knowing and meant for {D}."),
        timeline: [(0, "Evening: the stop."), (0, "Evening+10: the search.")],
        identified: "Lab Report",
        mood: .indifferent,
        genders: ["D": .male])

    static let shoesOut = SmallCases.make(
        key: "story.shoesOut",
        category: .property,
        headlines: ["Customer Wears New Shoes Out of Store"],
        law: "larcenyMerchant",
        spec: "Took merchandise valued at $130 from {V}, a shoe store, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} wore store shoes out the door on {DATE}. {D} tried on the shoes at 1 p.m. and walked out at 1:20 p.m. The shoes were worth $130.",
        state: [E(.video, 3, "Store Camera", "{D} walks out in new shoes."), E(.document, 2, "Price Tag", "A $130 tag on the display pair.")],
        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot.")],
        role: "Store clerk",
        exam: [.direct("What did the store camera show?", "\"{D} tried on a pair of shoes at about 1 p.m. and then walked out at 1:20 still wearing the new ones. The pair was worth $130.\""), .direct("Where was the price tag?", "\"A $130 tag was on the display pair. The shoes {DL} wore out matched that display.\""), .direct("What did {D} leave behind?", "\"A pair of old shoes in a box. I found them on the bench after {DL} left.\""), .direct("What happened when the defendant came to the shoe department?", "\"{DL} asked for a pair of running shoes in a size ten and sat down on the bench with the box. I brought two other sizes and left {DL} alone to try them.\""), .direct("What did you see on the camera later?", "\"{D.He} stands, pulls the new pair on, and walks to the front door while on a phone call. The old shoes are left behind in the open box.\""), .direct("What did you find afterward?", "\"A pair of worn gray sneakers in the box on the bench. The shoes on the display were gone, and the $130 tag was still on the empty box.\""), .cross("{D} came back the next day, didn't {D.he}?", "\"Yes. {D.He} came back the next day on {D.his} own and asked about the shoes.\""), .cross("Did the defendant try to hide the shoes?", "\"No. {D.He} walked out in the open past the front window. The shoes were on {D.his} feet.\""), .cross("Did anyone stop the defendant at the door?", "\"No. Nobody stopped {D.him}. The alarm did not go off, and we saw it later on camera.\""), .cross("No alarm went off at the door, did it?", "\"No. We had not put a tag on that pair yet, so nothing sounded.\""), .cross("{D} walked past the register in clear view, correct?", "\"Yes, straight past, and talking on the phone the whole time. {D.He} did not look around or hurry.\"")],
        theory: ("{D} walked out.", "Forgetful."),
        allocution: "\"I'm sorry.\"",
        truths: ("Old shoes were left in a box.", "{DL} came back the next day."),
        defendant: [.direct("Did you walk out wearing the store's shoes?", "\"Yes, I did. I forgot I still had them on. I was distracted and did not notice.\""), .direct("Why did you leave your old shoes?", "\"They were in the box, where I put them when I tried on the new ones. I did not mean to leave them behind.\""), .direct("Did you go back to the store?", "\"Yes. I came back the next day to return the shoes or pay for them. I realized my mistake.\""), .direct("What was going on during the visit?", "\"I was on a call with my manager about a shift change, and the call went longer than I expected. I tried on three sizes while talking.\""), .direct("How did you leave the store?", "\"I put my phone to my ear, grabbed my bag, and walked out as the call ended. I never looked down at my feet.\""), .direct("When did you realize what happened?", "\"About an hour later when I stopped to tie a shoe on the sidewalk. I saw the tag lining and felt my face go red.\""), .cross("It took you twenty minutes inside the store, didn't it?", "\"Yes. I was trying on different sizes. I was not planning to leave.\""), .cross("How can someone forget they have new shoes on their feet?", "\"I was on the phone and in a rush. I know it sounds strange, but that is what happened.\""), .cross("You came back only after you were on camera, didn't you?", "\"I came back because I realized. I did not know about the camera.\""), .cross("You walked past the registers, didn't you?", "\"I did, and I was talking the whole time. I did not notice any of it.\""), .cross("You came back the next day because you knew you were on camera, didn't you?", "\"I came back because I could not sleep thinking about it. I did not know about a camera until I got there.\"")],
        openings: ("{D} tried on a $130 pair of shoes at 1 p.m. and walked out of the store at 1:20 still wearing them, leaving old sneakers behind in the box. The store camera shows {D} walking past the registers.", "The defense witnesses will explain that {D} was on a work call, forgot the shoes were on {D.his} feet, and came back the next day. Someone who means to steal does not leave behind a worn pair in the box."),
        closings: ("The camera shows {D} walking out in new shoes, past the front window, without paying. Anyone who has bought shoes knows when a new pair is on their feet.", "{D} was distracted, forgot, and returned the next day to make it right. A forgetful customer who leaves a worn pair in the box and comes back is not a thief."),
        timeline: [(0, "1 p.m.: the fitting."), (0, "1:20 p.m.: the exit.")],
        identified: "Store Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let fakeSticker = SmallCases.make(
        key: "story.fakeSticker",
        category: .whiteCollar,
        headlines: ["Driver Displays Forged Inspection Sticker"],
        law: "forgery",
        spec: "Forged a vehicle inspection sticker of the State of North Carolina, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} placed a forged inspection sticker on a car on {DATE}. The stop came in the morning, and the sticker was checked ten minutes later. The number on the sticker had been copied from another car.",
        state: [E(.physical, 3, "Sticker", "A sticker with a copied number."), E(.document, 2, "Inspection Record", "No inspection on file under that number.")],
        defense: [E(.statement, 1, "Bought", "{DL} says {D.he} bought it from a shop.")],
        role: "Trooper",
        exam: [.direct("Why did you stop the car on {DATE}?", "\"It was a routine stop in the morning. About ten minutes later, I checked the inspection sticker on the windshield.\""), .direct("What did you find about the sticker?", "\"The number on it had been copied from another car. There was no inspection on file under that number.\""), .direct("What was the significance of that?", "\"It means the sticker was forged. A real sticker is tied to a real inspection record, and this one had none.\""), .direct("What do you check on an inspection sticker?", "\"I check the expiration month and year, the color, and the unique number printed at the bottom. Then I run the number through our system to confirm an inspection.\""), .direct("What did that check show here?", "\"There was no inspection on file under that number. When I searched further I found the number belonged to a different car altogether, in another county.\""), .direct("What else did you observe?", "\"The sticker had slightly different fonts and a faint ghost edge, as if it had been printed and cut out. A genuine one has a hologram strip and this had none.\""), .cross("{DL} says {D.he} bought it from a shop, doesn't {D.he}?", "\"I can't tell you whether a shop sold it. I only know the sticker was a forgery.\""), .cross("Could {DL} have known the sticker was fake?", "\"I can't say. A buyer who paid a shop might not look closely at the number.\""), .cross("Did {DL} act nervous?", "\"No. {D} was calm and polite. {D.He} handed over the registration, and I had no concerns about behavior.\""), .cross("{D} had a valid registration, didn't {D.he}?", "\"Yes. The registration and insurance were current, and the license was valid.\""), .cross("The sticker was in plain view on the windshield, wasn't it?", "\"It was on the driver's side where it belongs. Nothing was hidden or covered.\"")],
        theory: ("{D} forged a sticker.", "Bought it."),
        allocution: "\"I'm sorry.\"",
        truths: ("The shop does not exist.", "{DL} has a receipt."),
        defendant: [.direct("Where did you get the sticker?", "\"I bought it from a shop. I paid for what I thought was an inspection and a sticker. I didn't know it was fake.\""), .direct("Did you apply the sticker yourself?", "\"A person at the shop put it on. I thought everything was done properly.\""), .direct("Did you know the number was copied?", "\"No. I never looked at it. I trusted the shop. If I'd known, I would have gone to a real station.\""), .direct("Where did you go to get the inspection?", "\"A small garage on a back road that advertised same-day inspections. I did not go there often, and I do not remember the exact street.\""), .direct("What did you pay and receive?", "\"I paid cash, around forty dollars, and the worker put a sticker on the windshield. I was handed a receipt with a date but no business name I can read.\""), .direct("Why had the car not been inspected earlier?", "\"It was past due and I needed to drive to work. I was in a hurry and did not look closely at what was done.\""), .cross("You can't name the shop, can you?", "\"It was a small place. I don't remember the name. I paid cash. I know that sounds weak.\""), .cross("The sticker was on your windshield, wasn't it?", "\"Yes. It was in plain view. I wasn't hiding it.\""), .cross("You didn't check the inspection yourself, did you?", "\"No. That is on me. I assumed it was done right.\""), .cross("You never saw anyone actually inspect the car, did you?", "\"I saw someone drive it into the bay and walk around it. I did not watch the whole thing.\""), .cross("The receipt does not give a business address, does it?", "\"No. It has a stamp that is hard to read. I understand that makes my story harder to prove.\"")],
        openings: ("A trooper stopped {D}'s car and found an inspection sticker whose number had been copied from another car. No inspection was on file under that number, and the sticker lacked the hologram strip of a real one.", "Jurors will see a driver who paid a shop, displayed the sticker in plain view, and had valid registration and insurance. {D} did not make the sticker and trusted what was sold."),
        closings: ("A sticker with a number copied from another car, and no inspection on file. A forged sticker on a windshield tells everyone the car passed a test it never took.", "{D} paid a shop, displayed the sticker openly, and trusted what was sold. The State has not proved {D} knew the sticker was forged."),
        timeline: [(0, "Morning: the stop."), (0, "Morning+10: the check.")],
        identified: "Sticker",
        mood: .indifferent)

    static let bikeShareRiver = SmallCases.make(
