        defense: [E(.statement, 1, "Closure", "{DL} says the landlord evicted {D.him}.")],
        role: "Customer",
        exam: [.direct("What did you pay the tattoo shop?", "\"A booking deposit to {D}. The receipts show three deposits, totaling $500 across three customers.\""), .direct("When did the shop close?", "\"The shop went dark about a week after an eviction notice. The deposits were booked before the closure.\""), .direct("What did {D} tell you before it closed?", "\"Nothing about any problem. {D.He} kept taking deposits and never mentioned that the shop was being evicted.\""), .direct("How did you book your tattoo?", "\"I met {D.him} at the shop, picked a design, and paid a deposit by card. The receipt said the deposit applied to the session and was nonrefundable.\""), .direct("What happened when you went back?", "\"My appointment was two weeks out. When I arrived, the front door was locked, the lights were off, and there was a sign from the landlord on the glass.\""), .direct("How did you try to get your money back?", "\"I messaged {D.him} through the shop's page and by text for days and got nothing. Another customer posted that three people were out $500 together.\""), .cross("The eviction notice was real, wasn't it?", "\"Yes, there was a notice. I learned about it later, from {DL}'s landlord.\""), .cross("Did the defendant offer a refund?", "\"Eventually, yes. After I complained, {D.he} offered one.\""), .cross("Did you try to reach the defendant after the shop closed?", "\"Yes, many times. For a while there was no answer.\""), .cross("The notice on the door was dated a week before the closure, wasn't it?", "\"Yes, a landlord notice dated about seven days before. I did not see it until the day I arrived.\""), .cross("{D} offered a refund only after you complained, correct?", "\"Yes, after I posted a review and wrote to the state. Before that, {D.he} did not reply.\"")],
        theory: ("{D} took deposits.", "An eviction."),
